class Solution:
    def isMiddleElementUnique(self, nums: list[int]) -> bool:
        return nums.count(nums[len(nums) // 2]) == 1

class Solution {
    public boolean isMiddleElementUnique(int[] nums) {
        int cnt = 0;
        for (int x : nums) {
            if (x == nums[nums.length / 2]) {
                ++cnt;
            }
        }
        return cnt == 1;
    }
}

